int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long target;
    long long fuel;
    cin >> n >> target >> fuel;
    vector<vector<long long>> st(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> st[i][j];
        }
    }

    priority_queue<long long> heap;
    long long reach = fuel, i = 0, stops = 0;
    while (reach < target) {
        while (i < n && st[i][0] <= reach) {
            heap.push(st[i][1]);
            i++;
        }
        if (heap.empty()) {
            stops = -1;
            break;
        }
        reach += heap.top();
        heap.pop();
        stops++;
    }
    cout << stops << "\n";

    return 0;
}

