import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static long[] heap;
    static int heapSize;

    static void heapPush(long v) {
        int i = heapSize++;
        heap[i] = v;
        while (i > 0) {
            int p = (i - 1) / 2;
            if (heap[p] <= heap[i]) break;
            long t = heap[p];
            heap[p] = heap[i];
            heap[i] = t;
            i = p;
        }
    }

    static long heapPop() {
        long top = heap[0];
        heapSize--;
        if (heapSize > 0) {
            heap[0] = heap[heapSize];
            int i = 0;
            while (true) {
                int l = 2 * i + 1, rr = l + 1, m = i;
                if (l < heapSize && heap[l] < heap[m]) m = l;
                if (rr < heapSize && heap[rr] < heap[m]) m = rr;
                if (m == i) break;
                long t = heap[m];
                heap[m] = heap[i];
                heap[i] = t;
                i = m;
            }
        }
        return top;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long target = Long.parseLong(next());
        long fuel = Long.parseLong(next());
        long[][] st = new long[(int) n][2];
        for (int i = 0; i < st.length; i++) {
            for (int j = 0; j < st[i].length; j++) {
                st[i][j] = Long.parseLong(next());
            }
        }

        int count = (int) n;
        heap = new long[count + 5];
        heapSize = 0;
        long reach = fuel, stops = 0;
        int i = 0;
        while (reach < target) {
            while (i < count && st[i][0] <= reach) {
                heapPush(-st[i][1]);
                i++;
            }
            if (heapSize == 0) {
                stops = -1;
                break;
            }
            reach -= heapPop();
            stops++;
        }
        System.out.println(stops);
    }
}
